commands.terraform state show aws_s3_bucket.logs:
# aws_s3_bucket.logs:
resource "aws_s3_bucket" "logs" {
    arn                         = "arn:aws:s3:::prod-app-logs-bucket"
    bucket                      = "prod-app-logs-bucket"
    bucket_domain_name          = "prod-app-logs-bucket.s3.amazonaws.com"
    bucket_regional_domain_name = "prod-app-logs-bucket.s3.ap-south-1.amazonaws.com"
    hosted_zone_id              = "Z11RGJOFQNVJUP"
    id                          = "prod-app-logs-bucket"
    region                      = "ap-south-1"
    request_payer               = "BucketOwner"
    tags                        = {
        "Environment" = "production"
        "Name"        = "prod-app-logs"
    }
    tags_all                    = {
        "Environment" = "production"
        "Name"        = "prod-app-logs"
    }

    versioning {
        enabled    = true
        mfa_delete = false
    }

    server_side_encryption_configuration {
        rule {
            apply_server_side_encryption_by_default {
                sse_algorithm = "aws:kms"
            }
        }
    }
}

